{"command":"cd /workspace; cat > src/color.rs <<'EOF'
//! Minimal ANSI styling helpers for standard output.
//!
//! Colors are always emitted (even when stdout is not a terminal) which
//! mirrors how the tool behaves when piped.

use std::io::{self, Write};

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Color {
    Red,
    Green,
    Yellow,
}

impl Color {
    fn fg_code(self) -> &'static str {
        match self {
            Color::Red => "31",
            Color::Green => "32",
            Color::Yellow => "33",
        }
    }
}

/// A description of how text should look.
#[derive(Clone, Copy, Debug, Default)]
pub struct Style {
    pub fg: Option<Color>,
    pub bold: bool,
}

impl Style {
    pub fn new() -> Self {
        Style::default()
    }

    pub fn fg(mut self, color: Color) -> Self {
        self.fg = Some(color);
        self
    }

    pub fn bold(mut self) -> Self {
        self.bold = true;
        self
    }

    /// Escape sequence that activates this style. A reset is always emitted
    /// first so that previous styling does not leak into the new text.
    pub fn prefix(&self) -> String {
        let mut s = String::from("\x1b[0m");
        if self.bold {
            s.push_str("\x1b[1m");
        }
        if let Some(c) = self.fg {
            s.push_str("\x1b[");
            s.push_str(c.fg_code());
            s.push('m');
        }
        s
    }
}

pub const RESET: &str = "\x1b[0m";

/// Writer around stdout that knows how to switch styles.
pub struct Stdout {
    inner: io::Stdout,
}

impl Stdout {
    pub fn new() -> Self {
        Stdout {
            inner: io::stdout(),
        }
    }

    pub fn set_style(&mut self, style: Style) -> io::Result<()> {
        self.inner.write_all(style.prefix().as_bytes())
    }

    pub fn reset(&mut self) -> io::Result<()> {
        self.inner.write_all(RESET.as_bytes())
    }

    pub fn write_str(&mut self, s: &str) -> io::Result<()> {
        self.inner.write_all(s.as_bytes())
    }

    pub fn flush(&mut self) -> io::Result<()> {
        self.inner.flush()
    }

    /// Write `text` followed by a newline using `style`, then reset.
    pub fn styled_line(&mut self, style: Style, text: &str) -> io::Result<()> {
        self.set_style(style)?;
        self.write_str(text)?;
        self.write_str("\n")?;
        self.reset()
    }
}
EOF
echo done"}

