{"command":"cd /workspace; cat > src/logger.rs <<'EOF'
//! A small `RUST_LOG`-driven logger writing to stderr.
//!
//! Output format:
//!
//! ```text
//!  LEVEL target > message
//! ```
//!
//! Levels are colored (and the target is bold) only when stderr is a
//! terminal, `TERM` is set to something other than `dumb` and `NO_COLOR`
//! is not present in the environment.

use std::env;
use std::io::{self, IsTerminal, Write};
use std::sync::atomic::{AtomicUsize, Ordering};

use log::{Level, LevelFilter, Log, Metadata, Record};
use regex::Regex;

const ENV_VAR: &str = "RUST_LOG";

struct Directive {
    name: Option<String>,
    level: LevelFilter,
}

struct Logger {
    directives: Vec<Directive>,
    filter: Option<Regex>,
    color: bool,
}

static MAX_TARGET_WIDTH: AtomicUsize = AtomicUsize::new(0);

fn max_target_width(target: &str) -> usize {
    let current = MAX_TARGET_WIDTH.load(Ordering::Relaxed);
    if current < target.len() {
        MAX_TARGET_WIDTH.store(target.len(), Ordering::Relaxed);
        target.len()
    } else {
        current
    }
}

/// Parse a logging specification such as `crate1,crate2::mod=debug/regex`.
fn parse_spec(spec: &str) -> (Vec<Directive>, Option<Regex>) {
    let mut directives = Vec::new();

    let mut parts = spec.split('/');
    let mods = parts.next();
    let filter = parts.next();
    if parts.next().is_some() {
        eprintln!(
            "warning: invalid logging spec '{}', ignoring it (too many '/'s)",
            spec
        );
        return (directives, None);
    }

    if let Some(m) = mods {
        for s in m.split(',').map(|s| s.trim()) {
            if s.is_empty() {
                continue;
            }
            let mut pieces = s.split('=');
            let (level, name) = match (
                pieces.next(),
                pieces.next().map(|p| p.trim()),
                pieces.next(),
            ) {
                (Some(part0), None, None) => match part0.parse::<LevelFilter>() {
                    Ok(level) => (level, None),
                    Err(_) => (LevelFilter::max(), Some(part0)),
                },
                (Some(part0), Some(""), None) => (LevelFilter::max(), Some(part0)),
                (Some(part0), Some(part1), None) => match part1.parse::<LevelFilter>() {
                    Ok(level) => (level, Some(part0)),
                    Err(_) => {
                        eprintln!("warning: invalid logging spec '{}', ignoring it", part1);
                        continue;
                    }
                },
                _ => {
                    eprintln!("warning: invalid logging spec '{}', ignoring it", s);
                    continue;
                }
            };
            directives.push(Directive {
                name: name.map(|n| n.to_owned()),
                level,
            });
        }
    }

    let filter = filter.and_then(|f| match Regex::new(f) {
        Ok(re) => Some(re),
        Err(e) => {
            eprintln!("warning: invalid regex filter - {}", e);
            None
        }
    });

    (directives, filter)
}

fn stderr_supports_color() -> bool {
    if !io::stderr().is_terminal() {
        return false;
    }
    match env::var_os("TERM") {
        None => return false,
        Some(term) => {
            if term == "dumb" {
                return false;
            }
        }
    }
    if env::var_os("NO_COLOR").is_some() {
        return false;
    }
    true
}

impl Logger {
    fn enabled_for(&self, level: Level, target: &str) -> bool {
        // Directives are sorted by name length; the most specific match wins.
        for directive in self.directives.iter().rev() {
            match directive.name {
                Some(ref name) if !target.starts_with(&**name) => {}
                Some(_) | None => return level <= directive.level,
            }
        }
        false
    }

    fn matches(&self, record: &Record) -> bool {
        if !self.enabled_for(record.level(), record.target()) {
            return false;
        }
        if let Some(filter) = &self.filter {
            if !filter.is_match(&record.args().to_string()) {
                return false;
            }
        }
        true
    }

    fn max_level(&self) -> LevelFilter {
        self.directives
            .iter()
            .map(|d| d.level)
            .max()
            .unwrap_or(LevelFilter::Off)
    }
}

fn level_label(level: Level) -> &'static str {
    match level {
        Level::Trace => "TRACE",
        Level::Debug => "DEBUG",
        Level::Info => "INFO ",
        Level::Warn => "WARN ",
        Level::Error => "ERROR",
    }
}

fn level_color(level: Level) -> &'static str {
    match level {
        Level::Trace => "35",
        Level::Debug => "34",
        Level::Info => "32",
        Level::Warn => "33",
        Level::Error => "31",
    }
}

impl Log for Logger {
    fn enabled(&self, metadata: &Metadata) -> bool {
        self.enabled_for(metadata.level(), metadata.target())
    }

    fn log(&self, record: &Record) {
        if !self.matches(record) {
            return;
        }

        let target = record.target();
        let width = max_target_width(target);
        let level = record.level();

        let mut buf: Vec<u8> = Vec::new();
        let _ = buf.write_all(b" ");
        if self.color {
            let _ = write!(
                buf,
                "\x1b[0m\x1b[{}m{}\x1b[0m \x1b[0m\x1b[1m{: <width$}\x1b[0m > {}\n",
                level_color(level),
                level_label(level),
                target,
                record.args(),
                width = width
            );
        } else {
            let _ = write!(
                buf,
                "{} {: <width$} > {}\n",
                level_label(level),
                target,
                record.args(),
                width = width
            );
        }

        let stderr = io::stderr();
        let mut handle = stderr.lock();
        let _ = handle.write_all(&buf);
        let _ = handle.flush();
    }

    fn flush(&self) {
        let _ = io::stderr().flush();
    }
}

/// Install the global logger. Filtering is controlled by `RUST_LOG`; when
/// it is unset only errors are shown.
pub fn init() {
    let (mut directives, filter) = match env::var(ENV_VAR) {
        Ok(spec) => parse_spec(&spec),
        Err(_) => (Vec::new(), None),
    };

    if directives.is_empty() {
        directives.push(Directive {
            name: None,
            level: LevelFilter::Error,
        });
    } else {
        directives.sort_by(|a, b| {
            let alen = a.name.as_ref().map(|n| n.len()).unwrap_or(0);
            let blen = b.name.as_ref().map(|n| n.len()).unwrap_or(0);
            alen.cmp(&blen)
        });
    }

    let logger = Logger {
        directives,
        filter,
        color: stderr_supports_color(),
    };
    let max_level = logger.max_level();

    if log::set_boxed_logger(Box::new(logger)).is_ok() {
        log::set_max_level(max_level);
    }
}
EOF
echo done"}

