//! Locate an executable on `PATH`.

use std::env;
use std::ffi::CString;
use std::fmt;
use std::fs;
use std::os::unix::ffi::OsStrExt;
use std::path::{Component, Path, PathBuf};

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum WhichError {
    CannotFindBinaryPath,
}

impl fmt::Display for WhichError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            WhichError::CannotFindBinaryPath => write!(f, "cannot find binary path"),
        }
    }
}

impl std::error::Error for WhichError {}

fn is_executable(path: &Path) -> bool {
    let c_path = match CString::new(path.as_os_str().as_bytes()) {
        Ok(p) => p,
        Err(_) => return false,
    };
    // SAFETY: `c_path` is a valid NUL terminated string.
    unsafe { libc::access(c_path.as_ptr(), libc::X_OK) == 0 }
}

fn is_file(path: &Path) -> bool {
    fs::metadata(path).map(|m| m.is_file()).unwrap_or(false)
}

/// Expand a leading `~` component into the user's home directory.
fn tilde_expansion(path: &Path) -> PathBuf {
    let mut components = path.components();
    if let Some(Component::Normal(first)) = components.next() {
        if first == "~" {
            if let Some(mut home) = crate::home_dir() {
                home.extend(components);
                return home;
            }
        }
    }
    path.to_path_buf()
}

/// Search every entry in `PATH` for a file named `binary_name` that is both
/// a regular file and executable.
pub fn which(binary_name: &str) -> Result<PathBuf, WhichError> {
    let path_var = env::var_os("PATH").ok_or(WhichError::CannotFindBinaryPath)?;

    for dir in env::split_paths(&path_var) {
        let candidate = tilde_expansion(&dir).join(binary_name);
        if is_file(&candidate) && is_executable(&candidate) {
            return Ok(candidate);
        }
    }

    Err(WhichError::CannotFindBinaryPath)
}
