//! Persistent configuration stored as JSON in the user's config directory.

use std::env;
use std::fs;
use std::io;
use std::path::{Path, PathBuf};

use serde::{Deserialize, Serialize};

use crate::error::Error;

const APP_DIR_NAME: &str = "eureka";
const CONFIG_FILE_NAME: &str = "config.json";

#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct Config {
    pub repo: PathBuf,
}

pub struct ConfigManager {
    dir: PathBuf,
}

/// Base configuration directory: `$XDG_CONFIG_HOME` when set, otherwise
/// `$HOME/.config`.
fn base_config_dir() -> PathBuf {
    match env::var_os("XDG_CONFIG_HOME") {
        Some(xdg) => PathBuf::from(xdg),
        None => crate::home_dir()
            .expect("Could not determine home directory")
            .join(".config"),
    }
}

impl ConfigManager {
    pub fn new() -> Self {
        ConfigManager {
            dir: base_config_dir().join(APP_DIR_NAME),
        }
    }

    pub fn dir(&self) -> &Path {
        &self.dir
    }

    pub fn file_path(&self) -> PathBuf {
        self.dir.join(CONFIG_FILE_NAME)
    }

    pub fn dir_exists(&self) -> bool {
        self.dir.exists()
    }

    pub fn create_dir(&self) -> io::Result<()> {
        fs::create_dir_all(&self.dir)
    }

    /// Read the configuration. An empty file is treated as an empty config.
    pub fn read(&self) -> Result<Config, Error> {
        let content = fs::read_to_string(self.file_path())?;
        if content.is_empty() {
            return Ok(Config::default());
        }
        let config: Config = serde_json::from_str(&content)?;
        Ok(config)
    }

    pub fn write(&self, config: &Config) -> Result<(), Error> {
        let serialized = serde_json::to_string(config)?;
        fs::write(self.file_path(), serialized)?;
        Ok(())
    }

    pub fn clear(&self) -> io::Result<()> {
        fs::remove_file(self.file_path())
    }
}
