use std::env;
use std::path::{Path, PathBuf};

pub const ENV_CERT_FILE: &str = "SSL_CERT_FILE";
pub const ENV_CERT_DIR: &str = "SSL_CERT_DIR";

#[derive(Debug, Clone, Default)]
pub struct ProbeResult {
    pub cert_file: Option<PathBuf>,
    pub cert_dir: Option<PathBuf>,
}

const CERT_DIRS: &[&str] = &[
    "/var/ssl",
    "/usr/share/ssl",
    "/usr/local/ssl",
    "/usr/local/openssl",
    "/usr/local/etc/openssl",
    "/usr/local/share",
    "/usr/lib/ssl",
    "/usr/ssl",
    "/etc/openssl",
    "/etc/pki/ca-trust/extracted/pem",
    "/etc/pki/tls",
    "/etc/ssl",
    "/etc/certs",
    "/opt/etc/ssl",
    "/data/data/com.termux/files/usr/etc/tls",
    "/boot/system/data/ssl",
];

pub fn candidate_cert_dirs() -> impl Iterator<Item = &'static Path> {
    CERT_DIRS.iter().map(Path::new)
}

pub fn probe() -> ProbeResult {
    let mut result = ProbeResult::default();
    for dir in candidate_cert_dirs() {
        if result.cert_file.is_none() {
            for file in ["cert.pem", "certs.pem", "ca-bundle.pem", "cacert.pem", "ca-certificates.crt", "certs/ca-certificates.crt", "certs/ca-root-nss.crt", "certs/ca-bundle.crt", "CARootCertificates.pem", "tls-ca-bundle.pem"] {
                let candidate = dir.join(file);
                if candidate.is_file() {
                    result.cert_file = Some(candidate);
                    break;
                }
            }
        }
        if result.cert_dir.is_none() {
            let candidate = dir.join("certs");
            if candidate.is_dir() {
                result.cert_dir = Some(candidate);
            }
        }
        if result.cert_file.is_some() && result.cert_dir.is_some() {
            break;
        }
    }
    result
}

pub fn has_ssl_cert_env_vars() -> bool {
    env::var_os(ENV_CERT_FILE).is_some() || env::var_os(ENV_CERT_DIR).is_some()
}

/// Set `SSL_CERT_FILE` / `SSL_CERT_DIR` if they are unset and a certificate
/// store could be located. Returns whether both variables are now set.
pub unsafe fn init_openssl_env_vars() -> bool {
    try_init_openssl_env_vars()
}

pub unsafe fn try_init_openssl_env_vars() -> bool {
    let ProbeResult { cert_file, cert_dir } = probe();
    if let Some(file) = &cert_file {
        if env::var_os(ENV_CERT_FILE).is_none() {
