//! Linking shim for OpenSSL. Only the tiny surface needed by dependants is
//! exposed: library initialisation. The crate's real purpose is to link the
//! system `libssl`/`libcrypto` and tell dependent build scripts where the
//! headers live.

use std::os::raw::{c_int, c_void};
use std::ptr;
use std::sync::Once;

pub const OPENSSL_INIT_LOAD_SSL_STRINGS: u64 = 0x0020_0000;
pub const OPENSSL_INIT_LOAD_CRYPTO_STRINGS: u64 = 0x0000_0002;

extern "C" {
    pub fn OPENSSL_init_ssl(opts: u64, settings: *const c_void) -> c_int;
}

/// Initialise the OpenSSL library (idempotent).
pub fn init() {
    static INIT: Once = Once::new();
    INIT.call_once(|| unsafe {
        OPENSSL_init_ssl(
            OPENSSL_INIT_LOAD_SSL_STRINGS | OPENSSL_INIT_LOAD_CRYPTO_STRINGS,
            ptr::null(),
        );
    });
}
EOF
