//! crate's real purpose is to link the system `libssh2` and tell dependent
//! build scripts where the headers live.

use std::os::raw::c_int;
use std::sync::Once;

pub const LIBSSH2_INIT_NO_CRYPTO: c_int = 0x0001;

extern "C" {
    pub fn libssh2_init(flags: c_int) -> c_int;
    pub fn libssh2_exit();
}

/// Initialise libssh2 (idempotent).
pub fn init() {
